@router.delete("/clinical/prescriptions/{rx_pk}")
async def delete_prescription_draft(
    rx_pk: str,
    current_user: User = Depends(get_current_user)
):
    try:
        rx = PrescriptionDraft.get(rx_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Prescription draft not found")

    if rx.doctor_license_id != current_user.license_id and not current_user.is_clinical_director:
        raise HTTPException(status_code=403, detail="Forbidden: cannot delete prescription authored by another physician")

    PrescriptionDraft.delete(rx_pk)
    return {"status": "draft_deleted", "rx_pk": rx_pk}
